import React, { useCallback, useEffect, useMemo, useState } from 'react';
import {
  Button,
  Checkbox,
  DocumentHistoryModal,
  FormActions,
  Input,
  LeaveConfirmModal,
  LinCatalogUiSchemaEditorModal,
  LinPageLayout,
  Modal,
  NumberInput,
  SearchTextInput,
  Select,
  TextArea,
  dispatchAppToast,
  useCatalogTableBusy,
  useDirtyTracking,
  useLeaveConfirm,
  type CatalogUiSchema,
} from '@linm-soft-org/linm-web-common-components';
import { Tag, Popconfirm } from '@/components/common';
import {
  FPC_SENSITIVITY_VARIABLE_CATALOG_KIND,
  FPC_SENSITIVITY_VARIABLE_DOCUMENT_TYPE,
  erpDocumentHistoryClient,
} from '../../../config/documentHistoryClients';
import { fpcService } from '../../../services/fpc/service';
import type {
  SensitivityVariableDto,
  CreateSensitivityVariableDto,
  UpdateSensitivityVariableDto,
} from '../../../services/fpc/types';
import {
  catalogUiSchemaService,
  resolveApiErrorMessage,
} from '../../../services/catalogUiSchemaService';
import { useAppDispatch } from '../../../store/hooks';
import { useFpcPermissions } from '../../../utils/fpcPermissionCode';
import { matchesCodeOrName, normalizeCode } from '../../../utils/codeField';
import styles from './SensitivityVariablePage.module.css';

const TEST_ID = 'bien-nhay-cam';
const PAGE_SIZE = 50;

const UNIT_OPTIONS = [
  { value: 'money', label: 'Tiền (money)' },
  { value: 'percent', label: 'Phần trăm (percent)' },
  { value: 'days', label: 'Ngày (days)' },
];

type FormMode = 'create' | 'edit' | 'view';
type FormErrors = Partial<Record<'code' | 'name', string>>;

type FormState = {
  code: string;
  name: string;
  unit: string;
  costCode: string;
  defaultAmount: number;
  sortOrder: number;
  description: string;
  isActive: boolean;
};

const EMPTY_FORM: FormState = {
  code: '',
  name: '',
  unit: 'money',
  costCode: '',
  defaultAmount: 0,
  sortOrder: 50,
  description: '',
  isActive: true,
};

function dtoToForm(item: SensitivityVariableDto): FormState {
  return {
    code: item.code,
    name: item.name,
    unit: item.unit || 'money',
    costCode: item.costCode || '',
    defaultAmount: item.defaultAmount ?? 0,
    sortOrder: item.sortOrder ?? 0,
    description: item.description || '',
    isActive: item.isActive,
  };
}

function unitLabel(unit: string): string {
  if (unit === 'percent') return '%';
  if (unit === 'days') return 'ngày';
  return 'tiền';
}

export default function SensitivityVariablePage() {
  const dispatch = useAppDispatch();
  const { canManageSensitivityVariable, canDeleteSensitivityVariable } = useFpcPermissions();
  const { onDirtyChange, guardedNavigate, leaveConfirmModalProps } = useLeaveConfirm({
    message: 'Có thay đổi chưa được lưu. Đóng form sẽ mất dữ liệu đã nhập.',
  });
  const { markDirty, markClean } = useDirtyTracking(onDirtyChange);

  const [data, setData] = useState<SensitivityVariableDto[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchDraft, setSearchDraft] = useState('');
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [checkedIds, setCheckedIds] = useState<Set<string>>(new Set());

  const [modalOpen, setModalOpen] = useState(false);
  const [formMode, setFormMode] = useState<FormMode>('create');
  const [editingItem, setEditingItem] = useState<SensitivityVariableDto | null>(null);
  const [form, setForm] = useState<FormState>(EMPTY_FORM);
  const [errors, setErrors] = useState<FormErrors>({});
  const [submitting, setSubmitting] = useState(false);

  const [historyOpen, setHistoryOpen] = useState(false);
  const [historyItem, setHistoryItem] = useState<SensitivityVariableDto | null>(null);
  const [configOpen, setConfigOpen] = useState(false);
  const [rowMenu, setRowMenu] = useState<{ x: number; y: number; item: SensitivityVariableDto } | null>(null);

  const onHistoryError = useCallback(
    (message: string) => dispatchAppToast(dispatch, { message, type: 'error' }),
    [dispatch],
  );
  const onSchemaError = useCallback(
    (message: string) => dispatchAppToast(dispatch, { message, type: 'error' }),
    [dispatch],
  );
  const onSchemaSuccess = useCallback(
    (message: string) => dispatchAppToast(dispatch, { message, type: 'success' }),
    [dispatch],
  );
  const resolveSchemaError = useCallback(
    (err: unknown, fallback: string) => resolveApiErrorMessage(err, fallback),
    [],
  );
  const onSchemaSaved = useCallback((_schema: CatalogUiSchema) => {
    setConfigOpen(false);
  }, []);

  const { showTableLoading, pulseSearch } = useCatalogTableBusy(loading);
  const viewOnly = formMode === 'view';

  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const result = await fpcService.getSensitivityVariableList();
      setData(result);
    } catch {
      dispatchAppToast(dispatch, { message: 'Không thể tải danh mục biến nhạy cảm', type: 'error' });
      setData([]);
    } finally {
      setLoading(false);
    }
  }, [dispatch]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  useEffect(() => {
    const close = () => setRowMenu(null);
    window.addEventListener('click', close);
    return () => window.removeEventListener('click', close);
  }, []);

  const filtered = useMemo(
    () => data.filter(r => matchesCodeOrName(r.code, r.name, search, r.description)),
    [data, search],
  );

  const totalCount = filtered.length;
  const pageItems = useMemo(() => {
    const start = (page - 1) * PAGE_SIZE;
    return filtered.slice(start, start + PAGE_SIZE);
  }, [filtered, page]);

  const selectedItem = useMemo(
    () => data.find(d => d.id === selectedId) ?? null,
    [data, selectedId],
  );

  const handleSearch = () => {
    pulseSearch(() => {
      setSearch(searchDraft.trim());
      setPage(1);
      setSelectedId(null);
      setCheckedIds(new Set());
    });
  };

  const clearFieldError = (key: keyof FormErrors) => {
    setErrors(prev => {
      if (!prev[key]) return prev;
      const next = { ...prev };
      delete next[key];
      return next;
    });
  };

  const openCreate = () => {
    setEditingItem(null);
    setFormMode('create');
    setForm(EMPTY_FORM);
    setErrors({});
    markClean();
    setModalOpen(true);
  };

  const openEdit = (item: SensitivityVariableDto) => {
    setEditingItem(item);
    setSelectedId(item.id);
    setFormMode('edit');
    setForm(dtoToForm(item));
    setErrors({});
    markClean();
    setModalOpen(true);
  };

  const openView = (item: SensitivityVariableDto) => {
    setEditingItem(item);
    setSelectedId(item.id);
    setFormMode('view');
    setForm(dtoToForm(item));
    setErrors({});
    markClean();
    setModalOpen(true);
  };

  const openHistory = (item: SensitivityVariableDto) => {
    setHistoryItem(item);
    setHistoryOpen(true);
  };

  const closeFormModal = () => {
    guardedNavigate(() => {
      setModalOpen(false);
      setErrors({});
      markClean();
    });
  };

  const validate = (): boolean => {
    const next: FormErrors = {};
    if (!form.code.trim()) next.code = 'Mã bắt buộc';
    if (!form.name.trim()) next.name = 'Tên bắt buộc';
    setErrors(next);
    if (Object.keys(next).length > 0) {
      const el = document.querySelector<HTMLElement>(
        `[data-testid="${TEST_ID}-field-${next.code ? 'code' : 'name'}"]`,
      );
      el?.scrollIntoView({ behavior: 'smooth', block: 'center' });
      return false;
    }
    return true;
  };

  const handleSubmit = async () => {
    if (viewOnly || !validate()) return;
    setSubmitting(true);
    try {
      if (editingItem && formMode === 'edit') {
        const dto: UpdateSensitivityVariableDto = {
          name: form.name.trim(),
          unit: form.unit,
          costCode: form.costCode.trim() || undefined,
          defaultAmount: form.defaultAmount ?? 0,
          sortOrder: form.sortOrder ?? 0,
          description: form.description.trim() || undefined,
          isActive: form.isActive,
        };
        await fpcService.updateSensitivityVariable(editingItem.id, dto);
        dispatchAppToast(dispatch, { message: 'Đã cập nhật biến nhạy cảm', type: 'success' });
      } else {
        const dto: CreateSensitivityVariableDto = {
          code: normalizeCode(form.code),
          name: form.name.trim(),
          unit: form.unit,
          costCode: form.costCode.trim() || undefined,
          defaultAmount: form.defaultAmount ?? 0,
          sortOrder: form.sortOrder ?? 50,
          description: form.description.trim() || undefined,
          isActive: form.isActive,
        };
        await fpcService.createSensitivityVariable(dto);
        dispatchAppToast(dispatch, { message: 'Đã tạo biến nhạy cảm', type: 'success' });
      }
      setModalOpen(false);
      markClean();
      fetchData();
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Lỗi khi lưu biến nhạy cảm';
      dispatchAppToast(dispatch, { message: msg, type: 'error' });
    } finally {
      setSubmitting(false);
    }
  };

  const handleDelete = async (id: string) => {
    try {
      await fpcService.deleteSensitivityVariable(id);
      dispatchAppToast(dispatch, { message: 'Đã xóa biến nhạy cảm', type: 'success' });
      setSelectedId(null);
      setCheckedIds(prev => {
        const next = new Set(prev);
        next.delete(id);
        return next;
      });
      fetchData();
    } catch {
      dispatchAppToast(dispatch, { message: 'Lỗi khi xóa biến nhạy cảm', type: 'error' });
    }
  };

  const toggleCheck = (id: string) => {
    setCheckedIds(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  const allPageChecked = pageItems.length > 0 && pageItems.every(r => checkedIds.has(r.id));
  const toggleCheckAll = () => {
    setCheckedIds(prev => {
      const next = new Set(prev);
      if (allPageChecked) pageItems.forEach(r => next.delete(r.id));
      else pageItems.forEach(r => next.add(r.id));
      return next;
    });
  };

  const patchForm = <K extends keyof FormState>(key: K, value: FormState[K]) => {
    if (viewOnly) return;
    markDirty();
    if (key === 'code' || key === 'name') clearFieldError(key);
    setForm(f => ({ ...f, [key]: value }));
  };

  const modalTitle =
    formMode === 'view'
      ? 'Xem biến nhạy cảm'
      : formMode === 'edit'
        ? 'Sửa biến nhạy cảm'
        : 'Tạo biến nhạy cảm';

  return (
    <div className={styles.catalogListRoot} data-catalog-list-page data-testid={`${TEST_ID}-list`}>
      <LinPageLayout
        kind="catalog"
        testIdPrefix={TEST_ID}
        pageClassName={styles.catalogListPage}
        header={{
          title: 'Danh mục biến nhạy cảm',
          hint: 'Dùng làm mặc định khi tạo kịch bản · ma trận nhạy cảm sau khi chạy',
          titleIconClass: 'fas fa-sliders-h',
        }}
        listTitle="Danh sách biến"
        listRowMenuHelp
        filterMaxWidthPx={1000}
        showTableLoading={showTableLoading}
        catalogToolbar={{
          testIdPrefix: TEST_ID,
          canAdd: canManageSensitivityVariable,
          showView: !!selectedItem,
          showEdit: !!selectedItem && canManageSensitivityVariable,
          canDelete: (!!selectedItem || checkedIds.size > 0) && canDeleteSensitivityVariable,
          canHistory: !!selectedItem,
          selectedCount: checkedIds.size || (selectedItem ? 1 : 0),
          onAdd: openCreate,
          onView: () => selectedItem && openView(selectedItem),
          onEdit: () => selectedItem && openEdit(selectedItem),
          onHistory: () => selectedItem && openHistory(selectedItem),
          onRefresh: fetchData,
          onDelete: () => {
            const id = selectedItem?.id ?? [...checkedIds][0];
            if (id) void handleDelete(id);
          },
          showSchemaConfig: true,
          onEditConfig: () => setConfigOpen(true),
        }}
        filters={(
          <SearchTextInput
            label="Tìm kiếm"
            placeholder="Tìm mã, tên..."
            value={searchDraft}
            onChange={setSearchDraft}
            onSearch={handleSearch}
            testId={`${TEST_ID}-search-text`}
          />
        )}
        footerPagination={{
          page,
          pageSize: PAGE_SIZE,
          totalCount,
          onPageChange: setPage,
          itemLabel: 'biến',
        }}
        modals={(
          <>
            <LeaveConfirmModal {...leaveConfirmModalProps} />
            <LinCatalogUiSchemaEditorModal
              testIdPrefix={TEST_ID}
              catalogKind={FPC_SENSITIVITY_VARIABLE_CATALOG_KIND}
              isOpen={configOpen}
              onClose={() => setConfigOpen(false)}
              onSaved={onSchemaSaved}
              loadSchema={catalogUiSchemaService.get}
              saveSchema={catalogUiSchemaService.save}
              onError={onSchemaError}
              onSuccess={onSchemaSuccess}
              resolveErrorMessage={resolveSchemaError}
            />
            {historyItem ? (
              <DocumentHistoryModal
                isOpen={historyOpen}
                onClose={() => {
                  setHistoryOpen(false);
                  setHistoryItem(null);
                }}
                client={erpDocumentHistoryClient}
                documentType={FPC_SENSITIVITY_VARIABLE_DOCUMENT_TYPE}
                documentId={historyItem.id}
                documentCode={historyItem.code}
                testIdPrefix={TEST_ID}
                onError={onHistoryError}
              />
            ) : null}
          </>
        )}
      >
        {pageItems.length === 0 && !showTableLoading ? (
          <div className={styles.empty}>
            <i className="fas fa-inbox" />
            <p>{search.trim() ? 'Không tìm thấy biến phù hợp' : 'Chưa có biến nhạy cảm'}</p>
          </div>
        ) : (
          <table className={styles.table} data-testid={`${TEST_ID}-grid`}>
            <thead className={styles.stickyHead}>
              <tr>
                <th className={styles.thStt}>STT</th>
                <th className={styles.thCheck}>
                  <Checkbox
                    checked={allPageChecked}
                    onChange={toggleCheckAll}
                    aria-label="Chọn tất cả"
                    data-testid={`${TEST_ID}-check-all`}
                  />
                </th>
                <th className={styles.thCode}>Mã</th>
                <th className={styles.thName}>Tên biến</th>
                <th className={styles.thSort}>Đơn vị</th>
                <th className={styles.thCode}>Mã CP</th>
                <th className={styles.thSort}>Mặc định</th>
                <th className={styles.thSort}>Thứ tự</th>
                <th className={styles.thActive}>Trạng thái</th>
                <th className={styles.thActions} />
              </tr>
            </thead>
            <tbody>
              {pageItems.map((record, idx) => (
                <tr
                  key={record.id}
                  className={selectedId === record.id ? styles.rowSelected : undefined}
                  onClick={() => setSelectedId(record.id)}
                  onDoubleClick={() => openView(record)}
                  onContextMenu={e => {
                    e.preventDefault();
                    setSelectedId(record.id);
                    setRowMenu({ x: e.clientX, y: e.clientY, item: record });
                  }}
                >
                  <td className={styles.cellStt}>{(page - 1) * PAGE_SIZE + idx + 1}</td>
                  <td className={styles.cellCheck} onClick={e => e.stopPropagation()}>
                    <span onClick={e => e.stopPropagation()}>
                      <Checkbox
                        checked={checkedIds.has(record.id)}
                        onChange={() => toggleCheck(record.id)}
                        aria-label={`Chọn ${record.code}`}
                      />
                    </span>
                  </td>
                  <td className={styles.cellCode}><strong>{record.code}</strong></td>
                  <td className={styles.cellName}>{record.name}</td>
                  <td className={styles.cellSort}>{unitLabel(record.unit)}</td>
                  <td className={styles.cellCode}>{record.costCode || '—'}</td>
                  <td className={styles.cellSort}>
                    {record.defaultAmount.toLocaleString('vi-VN')}
                  </td>
                  <td className={styles.cellSort}>{record.sortOrder}</td>
                  <td className={styles.cellActive}>
                    {record.isActive
                      ? <Tag color="green">Kích hoạt</Tag>
                      : <Tag color="default">Tạm ngưng</Tag>}
                  </td>
                  <td className={styles.cellActions} onClick={e => e.stopPropagation()}>
                    <button
                      type="button"
                      className={styles.linkBtn}
                      title="Xem"
                      onClick={() => openView(record)}
                    >
                      <i className="fas fa-eye" />
                    </button>
                    {canManageSensitivityVariable && (
                      <button
                        type="button"
                        className={styles.linkBtn}
                        title="Sửa"
                        onClick={() => openEdit(record)}
                      >
                        <i className="fas fa-edit" />
                      </button>
                    )}
                    {canDeleteSensitivityVariable && (
                      <Popconfirm title="Xóa biến này?" onConfirm={() => handleDelete(record.id)}>
                        <button type="button" className={`${styles.linkBtn} ${styles.linkBtnDanger}`} title="Xóa">
                          <i className="fas fa-trash" />
                        </button>
                      </Popconfirm>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
            {totalCount > 0 && (
              <tfoot>
                <tr className={styles.totalRow}>
                  <td colSpan={10}>Tổng cộng: {totalCount} biến</td>
                </tr>
              </tfoot>
            )}
          </table>
        )}
      </LinPageLayout>

      {rowMenu && (
        <div
          className={styles.rowMenu}
          style={{ left: rowMenu.x, top: rowMenu.y }}
          data-testid={`${TEST_ID}-row-menu`}
          onClick={e => e.stopPropagation()}
        >
          <button type="button" onClick={() => { openView(rowMenu.item); setRowMenu(null); }}>Xem</button>
          {canManageSensitivityVariable && (
            <button type="button" onClick={() => { openEdit(rowMenu.item); setRowMenu(null); }}>Sửa</button>
          )}
          <button type="button" onClick={() => { openHistory(rowMenu.item); setRowMenu(null); }}>Lịch sử</button>
          {canDeleteSensitivityVariable && (
            <button
              type="button"
              className={styles.rowMenuDanger}
              onClick={() => { void handleDelete(rowMenu.item.id); setRowMenu(null); }}
            >
              Xóa
            </button>
          )}
        </div>
      )}

      <Modal isOpen={modalOpen} onClose={closeFormModal} title={modalTitle} size="md">
        <div
          className={`${styles.formFields} ${viewOnly ? styles.viewDisabled : ''}`}
          data-testid={`${TEST_ID}-form`}
        >
          <div className={styles.masterCodeNameRow}>
            <div data-testid={`${TEST_ID}-field-code`}>
              <Input
                label="Mã *"
                value={form.code}
                readOnly={viewOnly}
                disabled={formMode === 'edit'}
                error={errors.code}
                placeholder="VD: RENT"
                onChange={e => patchForm('code', normalizeCode(e.target.value))}
              />
            </div>
            <div data-testid={`${TEST_ID}-field-name`}>
              <Input
                label="Tên *"
                value={form.name}
                readOnly={viewOnly}
                error={errors.name}
                placeholder="VD: Tiền thuê mặt bằng"
                onChange={e => patchForm('name', e.target.value)}
              />
            </div>
          </div>
          <div className={styles.inlineRow}>
            <Select
              label="Đơn vị"
              value={form.unit}
              options={UNIT_OPTIONS}
              disabled={viewOnly}
              onChange={(e: React.ChangeEvent<HTMLSelectElement>) => patchForm('unit', e.target.value)}
            />
            <Input
              label="Mã CP (tuỳ chọn)"
              value={form.costCode}
              readOnly={viewOnly}
              placeholder="VD: RENT"
              onChange={e => patchForm('costCode', normalizeCode(e.target.value))}
            />
            <NumberInput
              label="Giá trị mặc định"
              value={form.defaultAmount}
              readOnly={viewOnly}
              onChange={v => patchForm('defaultAmount', Number.isFinite(v) ? v : 0)}
            />
            <NumberInput
              label="Thứ tự"
              value={form.sortOrder}
              readOnly={viewOnly}
              onChange={v => patchForm('sortOrder', Number.isFinite(v) ? v : 0)}
            />
          </div>
          <TextArea
            label="Mô tả"
            value={form.description}
            readOnly={viewOnly}
            rows={2}
            onChange={e => patchForm('description', e.target.value)}
          />
          <Checkbox
            label="Kích hoạt"
            checked={form.isActive}
            disabled={viewOnly}
            onChange={e => patchForm('isActive', e.target.checked)}
          />
          <FormActions align="end">
            {viewOnly ? (
              <>
                {canManageSensitivityVariable && editingItem && (
                  <Button variant="primary" onClick={() => setFormMode('edit')}>Sửa</Button>
                )}
                <Button variant="secondary" onClick={closeFormModal}>Đóng</Button>
              </>
            ) : (
              <>
                <Button variant="secondary" onClick={closeFormModal}>Hủy</Button>
                <Button variant="primary" onClick={() => void handleSubmit()} disabled={submitting}>
                  {submitting ? 'Đang lưu…' : 'Lưu'}
                </Button>
              </>
            )}
          </FormActions>
        </div>
      </Modal>
    </div>
  );
}
